#include <cstddef>

class IntVector
{
public:
    IntVector() = default;
    ~IntVector() { delete[] m_data; }

    IntVector(const IntVector&) = delete;
    IntVector& operator=(const IntVector&) = delete;

    void push_back(int value)
    {
        if (m_size == m_capacity) grow(m_capacity == 0 ? 4 : m_capacity * 2);
        m_data[m_size] = value;
        ++m_size;
    }

    void pop_back()
    {
        if (m_size > 0) --m_size;
    }

    void reserve(std::size_t n)
    {
        if (n > m_capacity) grow(n);
    }

    std::size_t size() const { return m_size; }
    std::size_t capacity() const { return m_capacity; }
    int& operator[](std::size_t i) { return m_data[i]; }

private:
    void grow(std::size_t newCapacity)
    {
        int* bigger{ new int[newCapacity] };
        for (std::size_t i{ 0 }; i < m_size; ++i) bigger[i] = m_data[i];
        delete[] m_data;
        m_data = bigger;
        m_capacity = newCapacity;
    }

    int* m_data{ nullptr };
    std::size_t m_size{ 0 };
    std::size_t m_capacity{ 0 };
};

unitTests:
TEST("starts empty") { IntVector v; CHECK_EQ(v.size(), std::size_t{ 0 }); CHECK_EQ(v.capacity(), std::size_t{ 0 }); }
TEST("push and read") { IntVector v; v.push_back(10); v.push_back(20); CHECK_EQ(v.size(), std::size_t{ 2 }); CHECK_EQ(v[0], 10); CHECK_EQ(v[1], 20); }
TEST("first growth is to 4, then doubling")
{
    IntVector v;
    v.push_back(1); CHECK_EQ(v.capacity(), std::size_t{ 4 });
    for (int i{ 0 }; i < 4; ++i) v.push_back(i);
    CHECK_EQ(v.capacity(), std::size_t{ 8 });
    for (int i{ 0 }; i < 4; ++i) v.push_back(i);
    CHECK_EQ(v.capacity(), std::size_t{ 16 });
    CHECK_EQ(v.size(), std::size_t{ 9 });
}
TEST("values survive growth") { IntVector v; for (int i{ 0 }; i < 100; ++i) v.push_back(i * 3); bool ok{ true }; for (int i{ 0 }; i < 100; ++i) ok = ok && v[static_cast<std::size_t>(i)] == i * 3; CHECK(ok); }
TEST("reserve grows to exactly n") { IntVector v; v.reserve(10); CHECK_EQ(v.capacity(), std::size_t{ 10 }); CHECK_EQ(v.size(), std::size_t{ 0 }); v.reserve(5); CHECK_EQ(v.capacity(), std::size_t{ 10 }); }
TEST("reserve keeps values") { IntVector v; v.push_back(7); v.reserve(50); CHECK_EQ(v[0], 7); }
TEST("pop_back") { IntVector v; v.push_back(1); v.push_back(2); v.pop_back(); CHECK_EQ(v.size(), std::size_t{ 1 }); v.pop_back(); v.pop_back(); CHECK_EQ(v.size(), std::size_t{ 0 }); }
TEST("writing through operator[]") { IntVector v; v.push_back(1); v[0] = 99; CHECK_EQ(v[0], 99); }
TEST("no leaks") { CHECK_NO_LEAK({ IntVector v; for (int i{ 0 }; i < 1000; ++i) v.push_back(i); v.reserve(5000); }); }

